1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
7	
8	/**
9	 * Create-owner step: the single duplicate check. Rejects the request with a 409 only when
10	 * the new owner's whole {@link IdentityKey} (normalized telephone, email and household id)
11	 * equals an existing owner's — a separate telephone, email or household on its own is not a
12	 * duplicate.
13	 *
14	 * <p>Runs after {@link AssignHousehold} (so the new owner already carries its final
15	 * {@code householdId} and any linked members carry theirs) and before {@link SaveOwner},
16	 * so both sides of the comparison are in their settled form.
17	 */
18	public class EnsureUniqueIdentity {
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
21	            throws DuplicateIdentityException {
22	        String identityKey = IdentityKey.of(owner);
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (identityKey.equals(IdentityKey.of(existing))) {
25	                throw new DuplicateIdentityException(identityKey);
26	            }
27	        }
28	    }
29	}
