1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.util.Locale;
5	import java.util.UUID;
6	
7	import org.springframework.samples.petclinic.model.Owner;
8	
9	/**
10	 * The single definition of an owner "household": owners sharing the same last name and
11	 * address. The last name is compared case-insensitively with runs of whitespace collapsed
12	 * to a single space; the address is compared in its canonical {@link AddressNormalizer}
13	 * form, so both membership and the identifier use the same normalized address that is
14	 * stored and returned. Provides the membership test and the stable identifier shared by
15	 * the household.
16	 *
17	 * <p>The identifier is derived deterministically from the normalized last name and
18	 * address, so every owner in the same household resolves to the same value regardless of
19	 * creation order.
20	 *
21	 * @see AssignHousehold assigns the shared identifier to the joining owners.
22	 * @see IdentityKey folds the household identifier into the owner's duplicate-detection key.
23	 */
24	final class Household {
25	
26	    private Household() {
27	    }
28	
29	    /** Whether {@code owner} belongs to the household keyed by {@code lastName} and {@code address}. */
30	    static boolean matches(Owner owner, String lastName, String address) {
31	        return normalizeName(lastName).equals(normalizeName(owner.getLastName()))
32	                && AddressNormalizer.normalize(address).equals(AddressNormalizer.normalize(owner.getAddress()));
33	    }
34	
35	    /** The stable identifier shared by every owner in the household keyed by {@code lastName} and {@code address}. */
36	    static String id(String lastName, String address) {
37	        String key = normalizeName(lastName) + "\n" + AddressNormalizer.normalize(address);
38	        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
39	    }
40	
41	    /** A last name trimmed and lower-cased, with internal whitespace runs collapsed to a single space. */
42	    private static String normalizeName(String value) {
43	        return value == null ? "" : value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
44	    }
45	}
