1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	
5	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
6	
7	/**
8	 * Converts a raw telephone into canonical E.164 form: a leading '+', a country code and
9	 * the national number with no separators. A number that already carries an explicit
10	 * '+&lt;country code&gt;' keeps it; otherwise the Australian country code '+61' is assumed
11	 * and a single leading '0' is dropped from the national digits. Spaces, dashes and
12	 * brackets are stripped, and the result must hold 8 to 15 digits after the '+', else the
13	 * number cannot form valid E.164 and is rejected with an {@link InvalidTelephoneException}.
14	 *
15	 * <p>For a recognised country code the national number must also be exactly the length that
16	 * country requires ('+61' expects 9 national digits, '+1' expects 10); a wrong length is
17	 * rejected with an {@link InvalidTelephoneException}. Unrecognised country codes are held to
18	 * the generic 8-to-15-digit rule only.
19	 *
20	 * <p>The single, shared definition of a normalized telephone: {@link NormalizeOwnerTelephone}
21	 * uses it to store the E.164 value, which then forms the telephone part of the owner's
22	 * {@link IdentityKey} used for duplicate detection.
23	 */
24	final class E164Telephone {
25	
26	    /** Country code assumed when the number carries no explicit '+' prefix. */
27	    private static final String DEFAULT_COUNTRY_CODE = "61";
28	
29	    /** Recognised country code -> exact number of national digits it requires. */
30	    private static final Map<String, Integer> NATIONAL_DIGITS = Map.of("61", 9, "1", 10);
31	
32	    private static final int MIN_DIGITS = 8;
33	
34	    private static final int MAX_DIGITS = 15;
35	
36	    private E164Telephone() {
37	    }
38	
39	    /**
40	     * Normalize {@code telephone} to E.164, or throw when it cannot form a valid number.
41	     */
42	    static String normalize(String telephone) throws InvalidTelephoneException {
43	        if (telephone == null) {
44	            throw new InvalidTelephoneException();
45	        }
46	        String trimmed = telephone.trim();
47	        boolean explicitCountryCode = trimmed.startsWith("+");
48	        String cleaned = trimmed.replaceAll("[\\s()\\-]", "");
49	        if (explicitCountryCode) {
50	            cleaned = cleaned.substring(1);
51	        }
52	        if (cleaned.isEmpty() || !cleaned.chars().allMatch(c -> c >= '0' && c <= '9')) {
53	            throw new InvalidTelephoneException();
54	        }
55	        String digits;
56	        if (explicitCountryCode) {
57	            digits = cleaned;
58	        }
59	        else {
60	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
61	            digits = DEFAULT_COUNTRY_CODE + national;
62	        }
63	        if (digits.length() < MIN_DIGITS || digits.length() > MAX_DIGITS) {
64	            throw new InvalidTelephoneException();
65	        }
66	        checkNationalLength(digits);
67	        return "+" + digits;
68	    }
69	
70	    /**
71	     * Enforce the national-number length required by a recognised country code. A number
72	     * whose leading digits match a known code but whose remaining (national) digits are the
73	     * wrong length is rejected; codes not in {@link #NATIONAL_DIGITS} are left to the caller's
74	     * generic length check.
75	     */
76	    private static void checkNationalLength(String digits) throws InvalidTelephoneException {
77	        for (Map.Entry<String, Integer> country : NATIONAL_DIGITS.entrySet()) {
78	            String code = country.getKey();
79	            if (digits.startsWith(code)) {
80	                int nationalLength = digits.length() - code.length();
81	                if (nationalLength != country.getValue()) {
82	                    throw new InvalidTelephoneException();
83	                }
84	                return;
85	            }
86	        }
87	    }
88	}
