1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Converts a raw street address into canonical form: leading and trailing whitespace
8	 * trimmed, internal runs of whitespace collapsed to a single space, upper-cased, and
9	 * common abbreviations expanded to their full word ({@code ST}&#8594;{@code STREET},
10	 * {@code RD}&#8594;{@code ROAD}, {@code AVE}&#8594;{@code AVENUE}). A {@code null} or
11	 * whitespace-only address normalizes to the empty string.
12	 *
13	 * <p>The single, shared definition of a normalized address: {@link NormalizeOwnerAddress}
14	 * uses it to store the canonical value, {@link ValidateOwnerFields} uses it to reject an
15	 * address that is blank once normalized, and {@link Household} uses it to compare
16	 * addresses for duplicate detection and the shared household identifier. The
17	 * transformation is idempotent, so normalizing an already-normalized address is a no-op.
18	 */
19	final class AddressNormalizer {
20	
21	    /** Whole-token abbreviations expanded to their full word (keys already upper-cased). */
22	    private static final Map<String, String> ABBREVIATIONS =
23	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
24	
25	    private AddressNormalizer() {
26	    }
27	
28	    /** Normalize {@code address} to canonical form, or the empty string when blank. */
29	    static String normalize(String address) {
30	        if (address == null) {
31	            return "";
32	        }
33	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
34	        if (collapsed.isEmpty()) {
35	            return "";
36	        }
37	        String[] tokens = collapsed.split(" ");
38	        StringBuilder sb = new StringBuilder(collapsed.length());
39	        for (int i = 0; i < tokens.length; i++) {
40	            if (i > 0) {
41	                sb.append(' ');
42	            }
43	            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
44	        }
45	        return sb.toString();
46	    }
47	}
