1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * Step of {@code POST /api/owners}: resolves the new owner's effective registration date and
10	 * ensures it falls on a business day. The effective date is the one supplied in the request,
11	 * or the server's current date when the request supplied none; either way, a weekend date is
12	 * rolled forward to the following Monday (see {@link BusinessDay}). Runs on the built owner so
13	 * both the persisted row and the response — and every value derived from the date, such as the
14	 * membership number's year segment — carry the adjusted value.
15	 */
16	public class ResolveOwnerRegistrationDate {
17	
18	    public void service(@Val Owner owner) {
19	        LocalDate effective = owner.getRegistrationDate();
20	        if (effective == null) {
21	            effective = LocalDate.now();
22	        }
