3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * The single definition of an owner's <em>identity key</em>: the value that decides when
9	 * two owners are the same person. It joins the owner's normalized telephone, email and
10	 * household identifier into one string, so a duplicate is an exact match of the whole key
11	 * rather than of any single field.
12	 *
13	 * <p>Key = {@code normalizedTelephone + '|' + (email or empty) + '|' + (householdId or empty)}.
14	 * All three parts are already stored in canonical form ({@link NormalizeOwnerTelephone}
15	 * stores the E.164 telephone, {@link NormalizeOwnerEmail} the lower-cased email and
16	 * {@link AssignHousehold} the shared household id), so the key is built from the owner's
17	 * stored fields; email is lower-cased defensively so the comparison is case-insensitive.
18	 *
19	 * <p>Because the telephone is part of the key, two members of the same household (same
20	 * {@code householdId}) with different telephones have different keys and are both allowed.
21	 *
22	 * @see EnsureUniqueIdentity rejects a create request whose identity key matches an existing owner.
23	 */
24	public final class IdentityKey {
25	
26	    private IdentityKey() {
27	    }
28	
29	    /** The identity key of an existing owner, derived from its stored fields. */
30	    public static String of(Owner owner) {
31	        return of(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
32	    }
33	
34	    /** The identity key for the given normalized telephone, email and household id. */
35	    public static String of(String telephone, String email, String householdId) {
36	        return part(telephone) + "|" + lowerCased(email) + "|" + part(householdId);
37	    }
38	
39	    /** A field value, or the empty string when absent. */
40	    private static String part(String value) {
41	        return value == null ? "" : value;
42	    }
43	
44	    /** An email lower-cased, or the empty string when absent. */
45	    private static String lowerCased(String email) {
46	        return email == null ? "" : email.toLowerCase(Locale.ROOT);
47	    }
48	}
