20	
21	/**
22	 * Maps Owner & OwnerDto using Mapstruct
23	 */
24	@Mapper(uses = PetMapper.class)
25	public interface OwnerMapper {
26	
27	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
28	    @Mapping(target = "initials", expression = "java(initials(owner))")
29	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
30	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
31	    @Mapping(target = "locality", expression = "java(locality(owner))")
32	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
33	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
34	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
35	    OwnerDto toOwnerDto(Owner owner);
36	
37	    /** The owner's derived identity key: normalized telephone, email and household id joined. */
38	    default String identityKey(Owner owner) {
39	        return IdentityKey.of(owner);
40	    }
41	
42	    /** Format an owner's name for display as 'LastName, FirstName'. */
43	    default String displayName(Owner owner) {
44	        return owner.getLastName() + ", " + owner.getFirstName();
45	    }
46	
47	    /** The upper-cased first letters of firstName and lastName, dot-separated with a trailing dot (e.g. 'J.S.'). */
48	    default String initials(Owner owner) {
49	        return initial(owner.getFirstName()) + initial(owner.getLastName());
50	    }
51	
52	    private String initial(String name) {
53	        return name == null || name.isEmpty() ? "" : Character.toUpperCase(name.charAt(0)) + ".";
54	    }
55	
56	    /** The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is the
57	     *  last two digits of the registration date's year (e.g. 'SPR-SMI-0007-M26'). Absent until both the
58	     *  customer code and registration date have been assigned. */
59	    default String membershipNumber(Owner owner) {
60	        String customerCode = owner.getCustomerCode();
61	        LocalDate registrationDate = owner.getRegistrationDate();
62	        if (customerCode == null || registrationDate == null) {
63	            return null;
64	        }
65	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
66	    }
67	
68	    /** The Luhn check digit (0-9) over the digits of the owner's customerCode; absent until the
69	     *  customer code has been assigned. */
70	    default Integer checkDigit(Owner owner) {
71	        String customerCode = owner.getCustomerCode();
72	        return customerCode == null ? null : Luhn.checkDigit(customerCode);
73	    }
74	
75	    /** The owner's region, read back from the region segment of its customerCode (the identity's
76	     *  {@code <REGION>-<HASH8>} form). Until the customer code has been assigned it falls back to
